screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const INVENTORY_TABLE = 2; // 在庫管理テーブル
  const PRODUCT_TABLE = 0;   // 商品マスタテーブル
  const DEMAND_TABLE = 8;    // 需要予測テーブル
  const SEASONAL_TABLE = 9;  // 季節変動パターンテーブル
  const ORDER_TABLE = 4;     // 発注履歴テーブル

  // DOM要素取得
  const inventoryTbody = container.querySelector('#inventory-tbody');
  const alertList = container.querySelector('#alert-list');
  const recommendedOrders = container.querySelector('#recommended-orders');

  // 在庫一覧の再描画
  function renderInventory(inventoryRows) {
    const productMap = new Map();
    (tables[PRODUCT_TABLE]?.records || []).forEach(p => {
      productMap.set(p.id, p);
    });

    inventoryTbody.innerHTML = inventoryRows.map(inv => {
      const product = productMap.get(inv.商品ID) || {};
      const statusColor = inv.在庫状態 === '不足' ? '#ff6a00' : 
                         inv.在庫状態 === '過剰' ? '#ffa500' : '#4ade80';
      const turnoverRate = calculateTurnoverRate(inv.商品ID);

      return `
        <tr data-id="${inv.id}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${inv.現在庫数 || 0}</td>
          <td style="text-align: right;">${inv.安全在庫数 || 0}</td>
          <td style="text-align: right;">${inv.発注点 || 0}</td>
          <td><span style="color: ${statusColor}; font-weight: 500;">${inv.在庫状態 || '正常'}</span></td>
          <td style="text-align: right;">${turnoverRate.toFixed(1)}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${inv.id}" style="font-size: 12px; padding: 4px 8px;">編集</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 在庫回転率計算（簡易版）
  function calculateTurnoverRate(productId) {
    const orders = tables[ORDER_TABLE]?.records || [];
    const productOrders = orders.filter(o => o.商品ID === productId);
    const totalOrdered = productOrders.reduce((sum, o) => sum + (o.発注数量 || 0), 0);
    return totalOrdered > 0 ? totalOrdered / 12 : 0; // 年間回転率の概算
  }

  // アラート表示
  function renderAlerts(inventoryRows) {
    const alerts = inventoryRows.filter(inv => {
      const current = inv.現在庫数 || 0;
      const reorderPoint = inv.発注点 || 0;
      return current <= reorderPoint;
    });

    const productMap = new Map();
    (tables[PRODUCT_TABLE]?.records || []).forEach(p => {
      productMap.set(p.id, p);
    });

    alertList.innerHTML = alerts.length === 0 ? 
      '<div style="color: var(--text-muted); font-size: 12px;">アラートはありません</div>' :
      alerts.map(inv => {
        const product = productMap.get(inv.商品ID) || {};
        return `
          <div style="padding: 8px; margin-bottom: 4px; background: rgba(255,106,0,0.1); border-radius: 4px; font-size: 12px;">
            <strong>${product.商品名 || '不明'}</strong> - 現在庫: ${inv.現在庫数}個 (発注点: ${inv.発注点}個)
          </div>
        `;
      }).join('');
  }

  // 発注推奨リスト表示
  function renderRecommendedOrders(inventoryRows) {
    const recommendations = inventoryRows.filter(inv => {
      const current = inv.現在庫数 || 0;
      const reorderPoint = inv.発注点 || 0;
      return current <= reorderPoint;
    }).slice(0, 5); // 上位5件

    const productMap = new Map();
    (tables[PRODUCT_TABLE]?.records || []).forEach(p => {
      productMap.set(p.id, p);
    });

    recommendedOrders.innerHTML = recommendations.length === 0 ?
      '<div style="color: var(--text-muted); font-size: 12px;">発注推奨商品はありません</div>' :
      recommendations.map(inv => {
        const product = productMap.get(inv.商品ID) || {};
        const recommendQty = (inv.発注点 || 0) * 2; // 発注点の2倍を推奨
        return `
          <div style="padding: 8px; margin-bottom: 4px; background: var(--bg-main); border-radius: 4px; font-size: 12px;">
            <div style="font-weight: 500;">${product.商品名 || '不明'}</div>
            <div style="color: var(--text-muted);">推奨発注量: ${recommendQty}個</div>
          </div>
        `;
      }).join('');
  }

  // KPI更新
  function updateKPIs(inventoryRows) {
    const productMap = new Map();
    (tables[PRODUCT_TABLE]?.records || []).forEach(p => {
      productMap.set(p.id, p);
    });

    // 総在庫金額
    const totalValue = inventoryRows.reduce((sum, inv) => {
      const product = productMap.get(inv.商品ID) || {};
      return sum + (inv.現在庫数 || 0) * (product.仕入価格 || 0);
    }, 0);

    // 発注点割れ商品数
    const belowReorderPoint = inventoryRows.filter(inv => 
      (inv.現在庫数 || 0) <= (inv.発注点 || 0)
    ).length;

    // 平均在庫回転率
    const avgTurnover = inventoryRows.reduce((sum, inv) => 
      sum + calculateTurnoverRate(inv.商品ID), 0) / Math.max(inventoryRows.length, 1);

    // 今月発注件数
    const thisMonth = new Date().toISOString().slice(0, 7);
    const monthlyOrders = (tables[ORDER_TABLE]?.records || []).filter(o => 
      o.発注日 && o.発注日.startsWith(thisMonth)
    ).length;

    container.querySelector('[data-testid="total-inventory-value"]').textContent = 
      `¥${totalValue.toLocaleString()}`;
    container.querySelector('[data-testid="below-reorder-point"]').textContent = 
      `${belowReorderPoint}件`;
    container.querySelector('[data-testid="avg-turnover-rate"]').textContent = 
      `${avgTurnover.toFixed(1)}回`;
    container.querySelector('[data-testid="monthly-orders"]').textContent = 
      `${monthlyOrders}件`;
  }

  // 需要予測チャート
  function initDemandChart() {
    const ctx = container.querySelector('#demand-chart').getContext('2d');
    const demandData = tables[DEMAND_TABLE]?.records || [];

    // 月別データ集計
    const monthlyData = {};
    demandData.forEach(d => {
      const month = d.予測対象年月 || '';
      if (month) {
        monthlyData[month] = (monthlyData[month] || 0) + (d.予測数量 || 0);
      }
    });

    const labels = Object.keys(monthlyData).sort().slice(-6); // 直近6ヶ月
    const values = labels.map(l => monthlyData[l] || 0);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '需要予測',
          data: values,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59,130,246,0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });
  }

  // 季節変動チャート
  function initSeasonalChart() {
    const ctx = container.querySelector('#seasonal-chart').getContext('2d');
    const seasonalData = tables[SEASONAL_TABLE]?.records || [];

    // 月別変動係数
    const monthlyCoeff = Array(12).fill(1.0);
    seasonalData.forEach(s => {
      const month = s.月;
      const coeff = parseFloat(s.季節変動係数) || 1.0;
      if (month >= 1 && month <= 12) {
        monthlyCoeff[month - 1] = coeff;
      }
    });

    const months = ['1月', '2月', '3月', '4月', '5月', '6月', 
                   '7月', '8月', '9月', '10月', '11月', '12月'];

    new Chart(ctx, {
      type: 'bar',
      data: {
        labels: months,
        datasets: [{
          label: '季節変動係数',
          data: monthlyCoeff,
          backgroundColor: '#10b981',
          borderColor: '#059669',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: { 
            beginAtZero: true,
            max: 2.0
          }
        }
      }
    });
  }

  // 検索・フィルター処理
  function performSearch() {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;
    const status = container.querySelector('#status-filter').value;

    window.aivicApi.list(INVENTORY_TABLE).then(rows => {
      if (!rows) return;

      const productMap = new Map();
      (tables[PRODUCT_TABLE]?.records || []).forEach(p => {
        productMap.set(p.id, p);
      });

      const filtered = rows.filter(inv => {
        const product = productMap.get(inv.商品ID) || {};

        // キーワード検索
        if (keyword && !((product.商品名 || '').toLowerCase().includes(keyword) || 
                        (product.商品コード || '').toLowerCase().includes(keyword))) {
          return false;
        }

        // カテゴリフィルター
        if (category && product.カテゴリ !== category) {
          return false;
        }

        // ステータスフィルター
        if (status && inv.在庫状態 !== status) {
          return false;
        }

        return true;
      });

      renderInventory(filtered);
      renderAlerts(filtered);
      renderRecommendedOrders(filtered);
      updateKPIs(filtered);
    });
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(INVENTORY_TABLE).then(rows => {
      if (!rows) return;

      const productMap = new Map();
      (tables[PRODUCT_TABLE]?.records || []).forEach(p => {
        productMap.set(p.id, p);
      });

      const headers = ['商品コード', '商品名', '現在庫数', '安全在庫数', '発注点', '在庫状態'];
      const csvData = [headers.join(',')];

      rows.forEach(inv => {
        const product = productMap.get(inv.商品ID) || {};
        const row = [
          product.商品コード || '',
          `"${product.商品名 || ''}"`,
          inv.現在庫数 || 0,
          inv.安全在庫数 || 0,
          inv.発注点 || 0,
          `"${inv.在庫状態 || ''}"`
        ];
        csvData.push(row.join(','));
      });

      const blob = new Blob(['\uFEFF' + csvData.join('\n')], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'inventory_status.csv';
      a.click();
      URL.revokeObjectURL(url);
    });
  }

  // 発注点設定更新
  function updateReorderSettings() {
    const productId = container.querySelector('#product-select').value;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const autoOrder = container.querySelector('#auto-order').checked;

    if (!productId) {
      alert('商品を選択してください');
      return;
    }

    // 在庫管理テーブルの該当レコードを更新
    window.aivicApi.list(INVENTORY_TABLE).then(rows => {
      if (!rows) return;

      const targetInv = rows.find(inv => inv.商品ID === productId);
      if (targetInv) {
        window.aivicApi.update(INVENTORY_TABLE, targetInv.id, {
          発注点: reorderPoint,
          安全在庫数: safetyStock
        }).then(updated => {
          if (updated) {
            alert('発注点設定を更新しました');
            performSearch(); // 一覧を再読み込み
          }
        });
      }
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(INVENTORY_TABLE).then(rows => {
    if (rows) {
      renderInventory(rows);
      renderAlerts(rows);
      renderRecommendedOrders(rows);
      updateKPIs(rows);
    }
  });

  // 商品選択肢を動的に設定
  const productSelect = container.querySelector('#product-select');
  (tables[PRODUCT_TABLE]?.records || []).forEach(product => {
    const option = document.createElement('option');
    option.value = product.id;
    option.textContent = `${product.商品コード} - ${product.商品名}`;
    productSelect.appendChild(option);
  });

  // イベントリスナー登録
  container.querySelector('#btn-search').addEventListener('click', performSearch);
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);
  container.querySelector('#btn-update-settings').addEventListener('click', updateReorderSettings);

  // 行レベル操作（編集）
  container.addEventListener('click', e => {
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const invId = editBtn.dataset.id;
      // 編集処理（簡易実装）
      window.aivicApi.list(INVENTORY_TABLE).then(rows => {
        if (!rows) return;
        const inv = rows.find(r => r.id === invId);
        if (inv) {
          const newReorderPoint = prompt('新しい発注点を入力してください:', inv.発注点 || 0);
          if (newReorderPoint !== null) {
            window.aivicApi.update(INVENTORY_TABLE, invId, {
              発注点: parseInt(newReorderPoint) || 0
            }).then(updated => {
              if (updated) {
                performSearch();
              }
            });
          }
        }
      });
    }
  });

  // チャート初期化
  setTimeout(() => {
    initDemandChart();
    initSeasonalChart();
  }, 100);
}

function(container, apiUrl, tables) {
  // チャート描画関数
  function drawForecastChart() {
    const canvas = container.querySelector('#forecast-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;

    for (let i = 1; i < 6; i++) {
      const y = (height / 6) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    for (let i = 1; i < 12; i++) {
      const x = 40 + ((width - 60) / 12) * i;
      ctx.beginPath();
      ctx.moveTo(x, 20);
      ctx.lineTo(x, height - 20);
      ctx.stroke();
    }

    // 実績データ（青線）
    const actualData = [120, 95, 150, 142, 125, 118, 135, 128, 140, 155, 162, 148];
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    actualData.forEach((value, index) => {
      const x = 40 + ((width - 60) / 12) * index;
      const y = height - 20 - ((value - 80) / 100) * (height - 40);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 予測データ（オレンジ線）
    const forecastData = [145, 138, 165, 158, 142, 135];
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();

    forecastData.forEach((value, index) => {
      const x = 40 + ((width - 60) / 12) * (6 + index);
      const y = height - 20 - ((value - 80) / 100) * (height - 40);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績', 50, 35);
    ctx.fillText('予測', 100, 35);

    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(30, 28, 15, 2);
    ctx.fillStyle = '#f59e0b';
    ctx.fillRect(80, 28, 15, 2);
  }

  function drawSeasonalChart() {
    const canvas = container.querySelector('#seasonal-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    // 季節変動係数データ
    const coefficients = [0.85, 0.92, 1.25, 1.18, 1.05, 0.98, 1.02, 1.08, 1.15, 1.22, 1.12, 0.95];
    const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];

    // バーチャート
    const barWidth = (width - 80) / 12;
    coefficients.forEach((coeff, index) => {
      const x = 40 + barWidth * index;
      const barHeight = (coeff - 0.5) * (height - 60) / 1.0;
      const y = height - 30 - barHeight;

      // バーの色（係数に応じて）
      if (coeff > 1.1) ctx.fillStyle = '#ef4444';
      else if (coeff < 0.9) ctx.fillStyle = '#3b82f6';
      else ctx.fillStyle = '#10b981';

      ctx.fillRect(x + 2, y, barWidth - 4, barHeight);

      // 月ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(months[index], x + barWidth/2, height - 10);

      // 係数値
      ctx.fillText(coeff.toFixed(2), x + barWidth/2, y - 5);
    });

    // 基準線（1.0）
    const baseY = height - 30 - (0.5 * (height - 60) / 1.0);
    ctx.strokeStyle = '#6b7280';
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(40, baseY);
    ctx.lineTo(width - 20, baseY);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // 係数テーブル再描画
  function renderCoefficients(data) {
    const tbody = container.querySelector('#coefficients-tbody');
    tbody.innerHTML = data.map(item => `
      <tr>
        <td>${item.month}</td>
        <td>${item.coefficient}</td>
        <td>${item.pattern}</td>
        <td style="color: ${item.change.startsWith('+') ? '#10b981' : item.change.startsWith('-') ? '#ef4444' : 'var(--text)'};">${item.change}</td>
      </tr>
    `).join('');
  }

  // 初期データ設定
  const initialCoefficients = [
    { month: '1月', coefficient: '0.85', pattern: '冬季低下', change: '-15%' },
    { month: '2月', coefficient: '0.92', pattern: '冬季低下', change: '-8%' },
    { month: '3月', coefficient: '1.25', pattern: '春季増加', change: '+25%' },
    { month: '4月', coefficient: '1.18', pattern: '春季増加', change: '+18%' },
    { month: '5月', coefficient: '1.05', pattern: '平常', change: '+5%' },
    { month: '6月', coefficient: '0.98', pattern: '平常', change: '-2%' },
    { month: '7月', coefficient: '1.02', pattern: '平常', change: '+2%' },
    { month: '8月', coefficient: '1.08', pattern: '夏季増加', change: '+8%' },
    { month: '9月', coefficient: '1.15', pattern: '秋季増加', change: '+15%' },
    { month: '10月', coefficient: '1.22', pattern: '秋季増加', change: '+22%' },
    { month: '11月', coefficient: '1.12', pattern: '秋季増加', change: '+12%' },
    { month: '12月', coefficient: '0.95', pattern: '年末調整', change: '-5%' }
  ];

  renderCoefficients(initialCoefficients);

  // 予測期間スライダー
  const slider = container.querySelector('#forecast-period');
  const label = container.querySelector('#forecast-period-label');
  slider.addEventListener('input', (e) => {
    label.textContent = `${e.target.value}ヶ月`;
  });

  // 期間切替タブ
  container.addEventListener('click', (e) => {
    const tabBtn = e.target.closest('.tab-btn');
    if (tabBtn) {
      container.querySelectorAll('.tab-btn').forEach(btn => {
        btn.style.background = 'transparent';
        btn.style.border = '1px solid rgba(255,255,255,0.18)';
        btn.style.color = 'var(--text)';
        btn.classList.remove('active');
      });
      tabBtn.style.background = 'var(--primary)';
      tabBtn.style.color = '#fff';
      tabBtn.style.border = 'none';
      tabBtn.classList.add('active');

      drawForecastChart(); // 期間に応じてチャート更新
    }
  });

  // 分析実行ボタン
  container.querySelector('#analyze-btn').addEventListener('click', async () => {
    const productId = container.querySelector('#product-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const forecastPeriod = container.querySelector('#forecast-period').value;
    const model = container.querySelector('input[name="model"]:checked').value;

    if (!productId) {
      alert('商品を選択してください');
      return;
    }

    // 分析実行（実際のAPIコール）
    try {
      const demandData = await window.aivicApi.list(8); // 需要予測テーブル
      const seasonalData = await window.aivicApi.list(9); // 季節変動パターンテーブル

      // 予測精度更新
      container.querySelector('#accuracy-value').textContent = '87.3%';
      container.querySelector('#confidence-value').textContent = '92.1%';
      container.querySelector('#error-value').textContent = '±12個';
      container.querySelector('#alert-message').textContent = '3月に需要急増の可能性';

      drawForecastChart();
      drawSeasonalChart();

    } catch (error) {
      console.error('分析実行エラー:', error);
    }
  });

  // CSVエクスポート
  container.querySelector('#export-csv-btn').addEventListener('click', () => {
    const csvContent = '\uFEFF月,係数,パターン,前年比\n' + 
      initialCoefficients.map(item => 
        `${item.month},${item.coefficient},${item.pattern},${item.change}`
      ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '季節変動係数.csv';
    link.click();
  });

  // 初期チャート描画
  setTimeout(() => {
    drawForecastChart();
    drawSeasonalChart();
  }, 100);
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderDeliveryRecords(records) {
    const tbody = container.querySelector('#delivery-records-tbody');
    tbody.innerHTML = records.map(record => {
      const delayClass = record.納期遅延日数 > 0 ? 'style="color: #ef4444;"' : record.納期遅延日数 < 0 ? 'style="color: #22c55e;"' : '';
      const statusColor = record.納品ステータス === '完納' ? '#22c55e' : record.納品ステータス === '一部納品' ? '#f59e0b' : '#6b7280';

      return `
        <tr data-id="${record.納期実績ID}">
          <td>${record.発注履歴ID || ''}</td>
          <td>${record.仕入先名 || ''}</td>
          <td>${record.商品名 || ''}</td>
          <td>${record.発注数量 || ''}${record.単位 || ''}</td>
          <td>${record.納期予定日 ? new Date(record.納期予定日).toLocaleDateString('ja-JP') : ''}</td>
          <td>${record.納期実績日 ? new Date(record.納期実績日).toLocaleDateString('ja-JP') : ''}</td>
          <td ${delayClass}>${record.納期遅延日数 || 0}日</td>
          <td><span style="background: ${statusColor}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 12px;">${record.納品ステータス || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${record.納期実績ID}" onclick="window.showScreen('scr-1780995966450')">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(5).then(records => {
    if (records) {
      renderDeliveryRecords(records);
      updateKPIs(records);
      drawCharts(records);
    }
  });

  // KPI更新関数
  function updateKPIs(records) {
    if (!records || records.length === 0) return;

    const totalOrders = records.length;
    const onTimeDeliveries = records.filter(r => (r.納期遅延日数 || 0) <= 0).length;
    const complianceRate = ((onTimeDeliveries / totalOrders) * 100).toFixed(1);
    const avgDelay = (records.reduce((sum, r) => sum + Math.max(0, r.納期遅延日数 || 0), 0) / totalOrders).toFixed(1);

    let reliabilityScore = 'A';
    if (complianceRate < 95) reliabilityScore = 'A-';
    if (complianceRate < 90) reliabilityScore = 'B+';
    if (complianceRate < 85) reliabilityScore = 'B';
    if (complianceRate < 80) reliabilityScore = 'B-';
    if (complianceRate < 75) reliabilityScore = 'C+';
    if (complianceRate < 70) reliabilityScore = 'C';

    container.querySelector('#compliance-rate').textContent = complianceRate + '%';
    container.querySelector('#avg-delay').textContent = avgDelay + '日';
    container.querySelector('#reliability-score').textContent = reliabilityScore;
    container.querySelector('#total-orders').textContent = totalOrders + '件';
  }

  // チャート描画関数
  function drawCharts(records) {
    // 納期実績推移チャート
    const trendCanvas = container.querySelector('#trend-chart');
    const trendCtx = trendCanvas.getContext('2d');
    trendCtx.clearRect(0, 0, 400, 200);

    // 背景
    trendCtx.fillStyle = '#1e293b';
    trendCtx.fillRect(0, 0, 400, 200);

    // グリッド線
    trendCtx.strokeStyle = '#374151';
    trendCtx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = 40 + (i * 30);
      trendCtx.beginPath();
      trendCtx.moveTo(40, y);
      trendCtx.lineTo(380, y);
      trendCtx.stroke();
    }

    // データライン
    trendCtx.strokeStyle = '#3b82f6';
    trendCtx.lineWidth = 2;
    trendCtx.beginPath();
    const points = [85, 88, 82, 90, 87, 89];
    points.forEach((point, index) => {
      const x = 40 + (index * 56);
      const y = 190 - (point * 1.5);
      if (index === 0) {
        trendCtx.moveTo(x, y);
      } else {
        trendCtx.lineTo(x, y);
      }
    });
    trendCtx.stroke();

    // ラベル
    trendCtx.fillStyle = '#9fb0d1';
    trendCtx.font = '12px sans-serif';
    trendCtx.fillText('納期遵守率推移', 10, 20);

    // 月別納期達成率チャート
    const monthlyCanvas = container.querySelector('#monthly-chart');
    const monthlyCtx = monthlyCanvas.getContext('2d');
    monthlyCtx.clearRect(0, 0, 400, 200);

    // 背景
    monthlyCtx.fillStyle = '#1e293b';
    monthlyCtx.fillRect(0, 0, 400, 200);

    // 棒グラフ
    const monthlyData = [92, 88, 85, 90, 87, 89, 91, 86, 88, 90, 85, 87];
    monthlyData.forEach((value, index) => {
      const x = 40 + (index * 28);
      const height = value * 1.5;
      const y = 190 - height;

      monthlyCtx.fillStyle = value >= 90 ? '#22c55e' : value >= 85 ? '#f59e0b' : '#ef4444';
      monthlyCtx.fillRect(x, y, 20, height);
    });

    monthlyCtx.fillStyle = '#9fb0d1';
    monthlyCtx.font = '12px sans-serif';
    monthlyCtx.fillText('月別達成率', 10, 20);

    // 遅延理由分類チャート（円グラフ）
    const reasonCanvas = container.querySelector('#delay-reason-chart');
    const reasonCtx = reasonCanvas.getContext('2d');
    reasonCtx.clearRect(0, 0, 300, 200);

    // 背景
    reasonCtx.fillStyle = '#1e293b';
    reasonCtx.fillRect(0, 0, 300, 200);

    const centerX = 150;
    const centerY = 100;
    const radius = 60;

    const reasons = [
      { label: '製造遅延', value: 40, color: '#ef4444' },
      { label: '輸送遅延', value: 25, color: '#f59e0b' },
      { label: '資材不足', value: 20, color: '#8b5cf6' },
      { label: 'その他', value: 15, color: '#6b7280' }
    ];

    let currentAngle = 0;
    reasons.forEach(reason => {
      const sliceAngle = (reason.value / 100) * 2 * Math.PI;

      reasonCtx.beginPath();
      reasonCtx.moveTo(centerX, centerY);
      reasonCtx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      reasonCtx.closePath();
      reasonCtx.fillStyle = reason.color;
      reasonCtx.fill();

      currentAngle += sliceAngle;
    });

    reasonCtx.fillStyle = '#9fb0d1';
    reasonCtx.font = '12px sans-serif';
    reasonCtx.fillText('遅延理由分析', 10, 20);
  }

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#search-input').value.toLowerCase();
    const records = await window.aivicApi.list(5);
    if (records) {
      const filtered = records.filter(record => 
        JSON.stringify(record).toLowerCase().includes(keyword)
      );
      renderDeliveryRecords(filtered);
    }
  });

  // 4. 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const supplierFilter = container.querySelector('#supplier-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    const records = await window.aivicApi.list(5);
    if (records) {
      let filtered = records;

      if (supplierFilter) {
        filtered = filtered.filter(r => r.仕入先ID === supplierFilter);
      }

      if (startDate) {
        filtered = filtered.filter(r => new Date(r.納期予定日) >= new Date(startDate));
      }

      if (endDate) {
        filtered = filtered.filter(r => new Date(r.納期予定日) <= new Date(endDate));
      }

      renderDeliveryRecords(filtered);
      updateKPIs(filtered);
      drawCharts(filtered);
    }
  });

  // 5. CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const records = await window.aivicApi.list(5);
    if (records) {
      const headers = ['発注番号', '仕入先名', '商品名', '発注数量', '納期予定日', '納期実績日', '遅延日数', '納品ステータス'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...records.map(record => [
          record.発注履歴ID || '',
          record.仕入先名 || '',
          record.商品名 || '',
          record.発注数量 || '',
          record.納期予定日 ? new Date(record.納期予定日).toLocaleDateString('ja-JP') : '',
          record.納期実績日 ? new Date(record.納期実績日).toLocaleDateString('ja-JP') : '',
          record.納期遅延日数 || 0,
          record.納品ステータス || ''
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '納期実績分析_' + new Date().toISOString().slice(0, 10) + '.csv';
      link.click();
    }
  });

  // 6. レポート出力
  container.querySelector('#btn-export-report').addEventListener('click', () => {
    alert('詳細レポートを生成中です...');
  });
}

function(container, apiUrl, tables) {
  const productTable = tables.find(t => t.tableName === '商品マスタ') || tables[0];
  const stockTable = tables.find(t => t.tableName === '在庫管理') || tables[1];
  const reorderTable = tables.find(t => t.tableName === '発注点設定') || tables[7];
  const demandTable = tables.find(t => t.tableName === '需要予測') || tables[8];

  let currentProducts = [];
  let selectedProductId = null;

  // 商品一覧の再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    if (!tbody) return;

    tbody.innerHTML = products.map(product => {
      const stock = stockTable.records?.find(s => s.商品ID === product.商品ID) || {};
      const reorderPoint = reorderTable.records?.find(r => r.商品ID === product.商品ID) || {};

      const currentStock = stock.現在庫数 || 0;
      const orderPoint = reorderPoint.発注点 || product.発注点 || 0;
      const safetyStock = reorderPoint.安全在庫 || product.安全在庫数 || 0;

      let status = '正常';
      let statusColor = '#22c55e';
      if (currentStock <= orderPoint) {
        status = '要発注';
        statusColor = '#ef4444';
      } else if (currentStock <= safetyStock) {
        status = '不足';
        statusColor = '#f59e0b';
      }

      return `
        <tr data-id="${product.商品ID}" class="product-row cursor-pointer hover:bg-opacity-50" style="background: ${selectedProductId === product.商品ID ? 'rgba(59, 130, 246, 0.1)' : 'transparent'};">
          <td style="color: var(--text);">${product.商品コード || ''}</td>
          <td style="color: var(--text);">${product.商品名 || ''}</td>
          <td style="color: var(--text);">${currentStock.toLocaleString()}</td>
          <td style="color: var(--text);">${orderPoint.toLocaleString()}</td>
          <td style="color: var(--text);">${safetyStock.toLocaleString()}</td>
          <td style="color: var(--text);">${Math.floor(Math.random() * 50 + 10)}/月</td>
          <td><span style="color: ${statusColor}; font-weight: 500;">${status}</span></td>
          <td>
            <button class="action-btn secondary select-btn" data-id="${product.商品ID}">選択</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 選択商品情報の表示
  function showSelectedProduct(product) {
    const infoDiv = container.querySelector('#selected-product-info');
    if (!infoDiv || !product) return;

    const stock = stockTable.records?.find(s => s.商品ID === product.商品ID) || {};
    const reorderPoint = reorderTable.records?.find(r => r.商品ID === product.商品ID) || {};

    infoDiv.innerHTML = `
      <div class="font-medium mb-1" style="color: var(--text);">${product.商品名}</div>
      <div class="text-sm" style="color: var(--text-muted);">コード: ${product.商品コード}</div>
      <div class="text-sm" style="color: var(--text-muted);">現在庫: ${(stock.現在庫数 || 0).toLocaleString()}${product.単位 || '個'}</div>
    `;

    // フォームに値を設定
    container.querySelector('#selected-product-id').value = product.商品ID;
    container.querySelector('#reorder-point').value = reorderPoint.発注点 || product.発注点 || '';
    container.querySelector('#order-quantity').value = reorderPoint.発注量 || '';
    container.querySelector('#safety-stock').value = reorderPoint.安全在庫 || product.安全在庫数 || '';
    container.querySelector('#lead-time').value = reorderPoint.リードタイム日数 || '';

    drawDemandChart(product.商品ID);
  }

  // 需要予測グラフの描画
  function drawDemandChart(productId) {
    const canvas = container.querySelector('#demand-chart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // キャンバスクリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ（実際は需要予測テーブルから取得）
    const months = ['10月', '11月', '12月', '1月', '2月', '3月'];
    const actual = [120, 135, 150, null, null, null];
    const forecast = [null, null, null, 140, 125, 160];

    const maxValue = 200;
    const padding = 40;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(width - padding, y);
      ctx.stroke();
    }

    // 実績線（青）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    let started = false;
    for (let i = 0; i < actual.length; i++) {
      if (actual[i] !== null) {
        const x = padding + (chartWidth / (months.length - 1)) * i;
        const y = padding + chartHeight - (actual[i] / maxValue) * chartHeight;
        if (!started) {
          ctx.moveTo(x, y);
          started = true;
        } else {
          ctx.lineTo(x, y);
        }
      }
    }
    ctx.stroke();

    // 予測線（オレンジ、点線）
    ctx.strokeStyle = '#f59e0b';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    started = false;
    for (let i = 0; i < forecast.length; i++) {
      if (forecast[i] !== null) {
        const x = padding + (chartWidth / (months.length - 1)) * i;
        const y = padding + chartHeight - (forecast[i] / maxValue) * chartHeight;
        if (!started) {
          ctx.moveTo(x, y);
          started = true;
        } else {
          ctx.lineTo(x, y);
        }
      }
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 月ラベル
    ctx.fillStyle = '#9ca3af';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    for (let i = 0; i < months.length; i++) {
      const x = padding + (chartWidth / (months.length - 1)) * i;
      ctx.fillText(months[i], x, height - 10);
    }
  }

  // 検索・フィルター
  function filterProducts() {
    const searchTerm = container.querySelector('#input-search').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;
    const stockStatus = container.querySelector('#stock-status-filter').value;

    let filtered = currentProducts.filter(product => {
      const matchesSearch = !searchTerm || 
        (product.商品名 && product.商品名.toLowerCase().includes(searchTerm)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(searchTerm));

      const matchesCategory = !category || product.カテゴリ === category;

      let matchesStatus = true;
      if (stockStatus) {
        const stock = stockTable.records?.find(s => s.商品ID === product.商品ID) || {};
        const reorderPoint = reorderTable.records?.find(r => r.商品ID === product.商品ID) || {};
        const currentStock = stock.現在庫数 || 0;
        const orderPoint = reorderPoint.発注点 || product.発注点 || 0;
        const safetyStock = reorderPoint.安全在庫 || product.安全在庫数 || 0;

        if (stockStatus === '要発注' && currentStock > orderPoint) matchesStatus = false;
        if (stockStatus === '不足' && (currentStock <= orderPoint || currentStock > safetyStock)) matchesStatus = false;
        if (stockStatus === '正常' && currentStock <= safetyStock) matchesStatus = false;
      }

      return matchesSearch && matchesCategory && matchesStatus;
    });

    renderProducts(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['商品コード', '商品名', '現在庫数', '発注点', '安全在庫数', '発注量', 'リードタイム'];
    const rows = currentProducts.map(product => {
      const stock = stockTable.records?.find(s => s.商品ID === product.商品ID) || {};
      const reorderPoint = reorderTable.records?.find(r => r.商品ID === product.商品ID) || {};

      return [
        product.商品コード || '',
        product.商品名 || '',
        stock.現在庫数 || 0,
        reorderPoint.発注点 || product.発注点 || 0,
        reorderPoint.安全在庫 || product.安全在庫数 || 0,
        reorderPoint.発注量 || '',
        reorderPoint.リードタイム日数 || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = '発注点管理_' + new Date().toISOString().slice(0, 10) + '.csv';
    a.click();
    URL.revokeObjectURL(url);
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(products => {
    if (products) {
      currentProducts = products;
      renderProducts(products);
    }
  });

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', filterProducts);

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // 商品選択
  container.addEventListener('click', e => {
    const selectBtn = e.target.closest('.select-btn');
    if (selectBtn) {
      selectedProductId = selectBtn.dataset.id;
      const product = currentProducts.find(p => p.商品ID === selectedProductId);
      if (product) {
        showSelectedProduct(product);
        renderProducts(currentProducts); // 選択状態を反映
      }
    }
  });

  // 発注点設定保存
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const productId = container.querySelector('#selected-product-id').value;
    if (!productId) {
      alert('商品を選択してください');
      return;
    }

    const supplierId = container.querySelector('#supplier-select').value;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;
    const orderQuantity = parseInt(container.querySelector('#order-quantity').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;

    if (!supplierId) {
      alert('仕入先を選択してください');
      return;
    }

    const reorderData = {
      商品ID: productId,
      仕入先ID: supplierId,
      発注点: reorderPoint,
      発注量: orderQuantity,
      安全在庫: safetyStock,
      リードタイム日数: leadTime,
      有効フラグ: true,
      適用開始日: new Date().toISOString(),
      作成者: 'current-user',
      更新者: 'current-user'
    };

    const saved = await window.aivicApi.save(7, reorderData);
    if (saved) {
      alert('発注点設定を保存しました');
      // 商品一覧を再描画
      window.aivicApi.list(0).then(products => {
        if (products) {
          currentProducts = products;
          renderProducts(products);
        }
      });
    }
  });

  // 推奨値計算
  container.querySelector('#btn-calculate').addEventListener('click', () => {
    const productId = container.querySelector('#selected-product-id').value;
    if (!productId) {
      alert('商品を選択してください');
      return;
    }

    // 簡易計算（実際はより複雑なロジック）
    const avgConsumption = Math.floor(Math.random() * 50 + 20);
    const leadTimeDays = parseInt(container.querySelector('#lead-time').value) || 7;
    const safetyFactor = 1.5;

    const recommendedReorderPoint = Math.ceil(avgConsumption * (leadTimeDays / 30) * safetyFactor);
    const recommendedOrderQuantity = Math.ceil(avgConsumption * 2);
    const recommendedSafetyStock = Math.ceil(avgConsumption * 0.5);

    container.querySelector('#reorder-point').value = recommendedReorderPoint;
    container.querySelector('#order-quantity').value = recommendedOrderQuantity;
    container.querySelector('#safety-stock').value = recommendedSafetyStock;

    alert(`推奨値を計算しました\n発注点: ${recommendedReorderPoint}\n発注量: ${recommendedOrderQuantity}\n安全在庫: ${recommendedSafetyStock}`);
  });

  // 初期グラフ描画
  setTimeout(() => {
    drawDemandChart(null);
  }, 100);
}

