        <div style="font-size: 14px; color: var(--text-muted); margin-bottom: 8px;">${productData.productName}</div>
        <div style="font-size: 24px; font-weight: 600; color: var(--text); margin-bottom: 4px;">¥${(productData.unitPrice || 0).toLocaleString()}</div>
        <div style="font-size: 12px; color: var(--text-muted);">${productData.supplierName}</div>
        <div style="font-size: 12px; color: var(--text-muted); margin-top: 8px;">適用開始: ${productData.startDate ? new Date(productData.startDate).toLocaleDateString('ja-JP') : ''}</div>
      </div>
    `;
  }

  // 価格履歴グラフの描画
  function drawPriceChart(productId) {
    const canvas = container.querySelector("#price-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!productId) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('商品を選択してください', canvas.width / 2, canvas.height / 2);
      return;
    }

    // 選択商品の価格履歴データを取得（サンプルデータ）
    const historyData = [
      { date: '2024-01', price: 1200 },
      { date: '2024-02', price: 1180 },
      { date: '2024-03', price: 1250 },
      { date: '2024-04', price: 1220 },
      { date: '2024-05', price: 1300 },
      { date: '2024-06', price: 1280 }
    ];

    if (historyData.length === 0) return;

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    const maxPrice = Math.max(...historyData.map(d => d.price));
    const minPrice = Math.min(...historyData.map(d => d.price));
    const priceRange = maxPrice - minPrice || 1;

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();
    }

    // 価格線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    historyData.forEach((point, index) => {
      const x = padding + (chartWidth / (historyData.length - 1)) * index;
      const y = padding + chartHeight - ((point.price - minPrice) / priceRange) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });

    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    historyData.forEach((point, index) => {
      const x = padding + (chartWidth / (historyData.length - 1)) * index;
      const y = padding + chartHeight - ((point.price - minPrice) / priceRange) * chartHeight;

      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });

    // 価格ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 4; i++) {
      const price = minPrice + (priceRange / 4) * (4 - i);
      const y = padding + (chartHeight / 4) * i + 3;
      ctx.fillText(`¥${Math.round(price).toLocaleString()}`, padding - 5, y);
    }
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    try {
      const priceHistoryData = await window.aivicApi.list(6); // 価格履歴テーブル
      const productData = await window.aivicApi.list(0); // 商品マスタ
      const supplierData = await window.aivicApi.list(1); // 仕入先マスタ

      if (priceHistoryData && productData && supplierData) {
        // データを結合して表示用に整形
        allPriceData = priceHistoryData.map(price => {
          const product = productData.find(p => p.id === price.productId);
          const supplier = supplierData.find(s => s.id === price.supplierId);
          return {
            ...price,
            productName: product?.productName || '',
            productCode: product?.productCode || '',
            supplierName: supplier?.supplierName || '',
            isLowestPrice: false, // 後で計算
            changeRate: Math.round((Math.random() - 0.5) * 20) // サンプル変動率
          };
        });

        // 最低価格の判定
        const productGroups = {};
        allPriceData.forEach(item => {
          if (!productGroups[item.productId]) {
            productGroups[item.productId] = [];
          }
          productGroups[item.productId].push(item);
        });

        Object.values(productGroups).forEach(group => {
          const minPrice = Math.min(...group.map(item => item.unitPrice || 0));
          group.forEach(item => {
            if (item.unitPrice === minPrice) {
              item.isLowestPrice = true;
            }
          });
        });

        renderPriceRows(allPriceData);
      } else {
        renderPriceRows([]);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderPriceRows([]);
    }
  }

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const supplierSelect = container.querySelector("#supplier-select").value;
    const productCode = container.querySelector("#product-code-input").value.trim();
    const productName = container.querySelector("#product-name-input").value.trim();
    const startDate = container.querySelector("#start-date-input").value;
    const endDate = container.querySelector("#end-date-input").value;

    let filteredData = allPriceData;

    if (supplierSelect) {
      filteredData = filteredData.filter(item => item.supplierCode === supplierSelect);
    }

    if (productCode) {
      filteredData = filteredData.filter(item => 
        item.productCode && item.productCode.toLowerCase().includes(productCode.toLowerCase())
      );
    }

    if (productName) {
      filteredData = filteredData.filter(item => 
        item.productName && item.productName.toLowerCase().includes(productName.toLowerCase())
      );
    }

    if (startDate) {
      filteredData = filteredData.filter(item => 
        item.startDate && new Date(item.startDate) >= new Date(startDate)
      );
    }

    if (endDate) {
      filteredData = filteredData.filter(item => 
        item.startDate && new Date(item.startDate) <= new Date(endDate)
      );
    }

    renderPriceRows(filteredData);
  });

  // 4. クリア機能
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#supplier-select").value = "";
    container.querySelector("#product-code-input").value = "";
    container.querySelector("#product-name-input").value = "";
    container.querySelector("#start-date-input").value = "";
    container.querySelector("#end-date-input").value = "";
    renderPriceRows(allPriceData);
  });

  // 5. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const data = await window.aivicApi.list(6);
      if (!data) return;

      const headers = ['価格履歴ID', '商品ID', '仕入先ID', '適用開始日', '適用終了日', '単価', '最小発注数量', '価格変更理由'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...data.map(row => [
          row.id || '',
          row.productId || '',
          row.supplierId || '',
          row.startDate || '',
          row.endDate || '',
          row.unitPrice || '',
          row.minOrderQuantity || '',
          row.priceChangeReason || ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = 'price_history_export.csv';
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
    }
  });

  // 6. 行選択とイベントデリゲーション
  container.addEventListener("click", (e) => {
    const row = e.target.closest(".price-row");
    if (row) {
      selectedProductId = row.dataset.id;

      // 選択行のハイライト
      container.querySelectorAll(".price-row").forEach(r => r.style.background = "");
      row.style.background = "rgba(59, 130, 246, 0.1)";

      // 選択商品の価格情報を表示
      const selectedData = allPriceData.find(item => item.id === selectedProductId);
      updateCurrentPriceDisplay(selectedData);
      drawPriceChart(selectedProductId);
    }
  });

  // 7. 関連機能ボタン
  container.querySelector("#btn-order-history").addEventListener("click", () => {
    window.showScreen("scr-1780995859623"); // 発注実行・履歴管理画面
  });

  container.querySelector("#btn-supplier-eval").addEventListener("click", () => {
    window.showScreen("scr-1780995883650"); // 仕入先評価・選定支援画面
  });

  container.querySelector("#btn-inventory-check").addEventListener("click", () => {
    window.showScreen("scr-1780995849791"); // 在庫状況・発注点管理画面
  });

  // 初期化
  loadInitialData();
  drawPriceChart(null);
}

