function(container, apiUrl, tables) {
  let selectedSupplierId = null;
  let allSuppliers = [];
  let allOrders = [];
  let allDeliveries = [];
  let allPrices = [];
  let allEvaluations = [];

  // 仕入先一覧の再描画
  function renderSuppliers(suppliers) {
    const tbody = container.querySelector('#supplier-tbody');
    tbody.innerHTML = suppliers.map(s => {
      const evaluation = allEvaluations.find(e => e.仕入先ID === s.仕入先ID) || {};
      const deliveryRate = evaluation.納期遵守率 || 0;
      const rank = evaluation.評価ランク || '-';

      return `
        <tr data-id="${s.仕入先ID}" class="supplier-row cursor-pointer hover:bg-opacity-50" style="background: ${selectedSupplierId === s.仕入先ID ? 'rgba(59, 130, 246, 0.1)' : 'transparent'};">
          <td>${s.仕入先名 || ''}</td>
          <td><span class="px-2 py-1 rounded text-xs" style="background: ${getRankColor(rank)}; color: #fff;">${rank}</span></td>
          <td>${deliveryRate}%</td>
        </tr>
      `;
    }).join('');
  }

  function getRankColor(rank) {
    switch(rank) {
      case 'A': return '#22c55e';
      case 'B': return '#3b82f6';
      case 'C': return '#f59e0b';
      case 'D': return '#ef4444';
      default: return '#6b7280';
    }
  }

  // 詳細情報の更新
  function updateSupplierDetail(supplierId) {
    const supplier = allSuppliers.find(s => s.仕入先ID === supplierId);
    const evaluation = allEvaluations.find(e => e.仕入先ID === supplierId) || {};
    const orders = allOrders.filter(o => o.仕入先ID === supplierId);
    const deliveries = allDeliveries.filter(d => d.仕入先ID === supplierId);

    if (!supplier) return;

    const detailEl = container.querySelector('#supplier-detail');
    detailEl.innerHTML = `
      <div class="space-y-2 text-sm">
        <div><strong style="color: var(--text);">${supplier.仕入先名}</strong></div>
        <div style="color: var(--text-muted);">コード: ${supplier.仕入先コード || ''}</div>
        <div style="color: var(--text-muted);">担当者: ${supplier.担当者名 || ''}</div>
        <div style="color: var(--text-muted);">電話: ${supplier.電話番号 || ''}</div>
      </div>
    `;

    // KPI更新
    const deliveryRate = evaluation.納期遵守率 || 0;
    const qualityScore = evaluation.品質評価点 || 0;
    const delayedDeliveries = deliveries.filter(d => d.納期遅延日数 > 0).length;
    const delayRate = deliveries.length > 0 ? Math.round((delayedDeliveries / deliveries.length) * 100) : 0;
    const defectRate = Math.max(0, 100 - qualityScore);

    container.querySelector('#kpi-delivery').textContent = `${deliveryRate}%`;
    container.querySelector('#kpi-quality').textContent = `${qualityScore}点`;
    container.querySelector('#kpi-delay').textContent = `${delayRate}%`;
    container.querySelector('#kpi-defect').textContent = `${defectRate}%`;

    // 発注実績更新
    const totalAmount = orders.reduce((sum, o) => sum + (o.発注金額 || 0), 0);
    const avgPrice = orders.length > 0 ? Math.round(totalAmount / orders.length) : 0;

    container.querySelector('#order-count').textContent = `${orders.length}回`;
    container.querySelector('#order-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#order-avg-price').textContent = `¥${avgPrice.toLocaleString()}`;

    // グラフ更新
    drawDeliveryChart(deliveries);
    drawPriceChart(supplierId);
  }

  // 納期実績グラフ
  function drawDeliveryChart(deliveries) {
    const canvas = container.querySelector('#delivery-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (deliveries.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width/2, canvas.height/2);
      return;
    }

    // 月別集計
    const monthlyData = {};
    deliveries.forEach(d => {
      if (!d.納期実績日) return;
      const month = d.納期実績日.substring(0, 7); // YYYY-MM
      if (!monthlyData[month]) monthlyData[month] = { total: 0, onTime: 0 };
      monthlyData[month].total++;
      if (d.納期遅延日数 <= 0) monthlyData[month].onTime++;
    });

    const months = Object.keys(monthlyData).sort().slice(-6); // 直近6ヶ月
    const rates = months.map(m => monthlyData[m].onTime / monthlyData[m].total * 100);

    // グラフ描画
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / months.length * 0.8;
    const maxRate = 100;

    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;

    // Y軸線
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(`${100 - i * 25}%`, padding - 5, y + 3);
    }

    // バー描画
    rates.forEach((rate, i) => {
      const x = padding + (chartWidth / months.length) * i + (chartWidth / months.length - barWidth) / 2;
      const barHeight = (rate / maxRate) * chartHeight;
      const y = padding + chartHeight - barHeight;

      ctx.fillStyle = rate >= 90 ? '#22c55e' : rate >= 70 ? '#f59e0b' : '#ef4444';
      ctx.fillRect(x, y, barWidth, barHeight);

      // 月ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(months[i].substring(5), x + barWidth/2, canvas.height - 5);
    });
  }

  // 価格推移グラフ
  function drawPriceChart(supplierId) {
    const canvas = container.querySelector('#price-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const prices = allPrices.filter(p => p.仕入先ID === supplierId).sort((a, b) => 
      new Date(a.適用開始日) - new Date(b.適用開始日)
    );

    if (prices.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('価格データがありません', canvas.width/2, canvas.height/2);
      return;
    }

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    const minPrice = Math.min(...prices.map(p => p.単価));
    const maxPrice = Math.max(...prices.map(p => p.単価));
    const priceRange = maxPrice - minPrice || 1;

    // 背景グリッド
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // 価格線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    prices.forEach((price, i) => {
      const x = padding + (chartWidth / (prices.length - 1)) * i;
      const y = padding + chartHeight - ((price.単価 - minPrice) / priceRange) * chartHeight;

      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);

      // ポイント
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.stroke();
  }

  // 検索処理
  function performSearch() {
    const supplierName = container.querySelector('#supplier-search').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;
    const dateFrom = container.querySelector('#date-from').value;
    const dateTo = container.querySelector('#date-to').value;

    let filtered = allSuppliers.filter(s => {
      if (supplierName && !s.仕入先名.toLowerCase().includes(supplierName)) return false;
      return true;
    });

    renderSuppliers(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['仕入先名', '仕入先コード', '評価ランク', '納期遵守率', '品質評価点', '発注回数', '発注金額'];
    const rows = allSuppliers.map(s => {
      const evaluation = allEvaluations.find(e => e.仕入先ID === s.仕入先ID) || {};
      const orders = allOrders.filter(o => o.仕入先ID === s.仕入先ID);
      const totalAmount = orders.reduce((sum, o) => sum + (o.発注金額 || 0), 0);

      return [
        s.仕入先名 || '',
        s.仕入先コード || '',
        evaluation.評価ランク || '',
        evaluation.納期遵守率 || 0,
        evaluation.品質評価点 || 0,
        orders.length,
        totalAmount
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${cell}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = '仕入先実績.csv';
    a.click();
    URL.revokeObjectURL(url);
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(1), // 仕入先マスタ
    window.aivicApi.list(4), // 発注履歴
    window.aivicApi.list(5), // 納期実績
    window.aivicApi.list(6), // 価格履歴
    window.aivicApi.list(10) // 仕入先評価指標
  ]).then(([suppliers, orders, deliveries, prices, evaluations]) => {
    allSuppliers = suppliers || tables[1]?.records || [];
    allOrders = orders || tables[4]?.records || [];
    allDeliveries = deliveries || tables[5]?.records || [];
    allPrices = prices || tables[6]?.records || [];
    allEvaluations = evaluations || tables[10]?.records || [];

    renderSuppliers(allSuppliers);
  });

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', performSearch);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 仕入先選択
  container.addEventListener('click', (e) => {
    const row = e.target.closest('.supplier-row');
    if (row) {
      selectedSupplierId = row.dataset.id;
      renderSuppliers(allSuppliers);
      updateSupplierDetail(selectedSupplierId);
    }
  });

  // 画面遷移
  container.querySelector('#btn-supplier-detail').addEventListener('click', () => {
    window.showScreen('scr-1780995936014');
  });

  container.querySelector('#btn-evaluation').addEventListener('click', () => {
    window.showScreen('scr-1780995914314');
  });
}
